  rdfs:comment "A wire or combination of wires, with consistent electrical characteristics, building a single electrical system, used to carry alternating current between points in the power system. For symmetrical, transposed three phase lines, it is sufficient to use attributes of the line segment, which describe impedances and admittances for the entire length of the segment.  Additionally impedances can be computed by using length and associated per length impedances. The BaseVoltage at the two ends of ACLineSegments"@en ;
  rdfs:subClassOf cim:Conductor .

cim:SvPowerFlow ;
  rdfs:label "SvPowerFlow" ;
  rdfs:comment "State variable for power flow. Load convention is used for flow direction. This means flow out from the TopologicalNode into the equipment is positive."@en .

cimr:Equipment.Terminals ;
  a owl:ObjectProperty ;
  rdfs:label "terminals" ;
  rdfs:comment "Terminals of the equipment" ;
  owl:inverseOf cimr:Terminal.Equipment ;
  rdfs:domain cim:Equipment ;
  rdfs:range cim:Terminal .

cim:Terminal.SvPowerFlow ;
  a owl:ObjectProperty ;
  a owl:FunctionalProperty ;
  a owl:InverseFunctionalProperty ;
  rdfs:label "SvPowerFlow" ;
  rdfs:comment "The power flow state variable associated with the terminal."@en ;
  cims:multiplicity cims:M:0..1 ;
  owl:inverseOf cim:SvPowerFlow.Terminal ;
  rdfs:domain cim:Terminal ;
  rdfs:range cim:SvPowerFlow .

