  a owl:InverseFunctionalProperty ;
  rdfs:label "Terminals" ;
  rdfs:comment "Conducting equipment have terminals that may be connected to other conducting equipment terminals via connectivity nodes or topological nodes."@en ;
  cims:multiplicity cims:M:0..n ;
  owl:inverseOf cim:Terminal.ConductingEquipment ;
  rdfs:domain cim:ConductingEquipment ;
  rdfs:range cim:Terminal .

cim:Terminal.TopologicalNode ;
  a owl:ObjectProperty ;
  a owl:FunctionalProperty ;
  rdfs:label "TopologicalNode" ;
  rdfs:comment "The topological node associated with the terminal.   This can be used as an alternative to the connectivity node path to topological node, thus making it unnecessary to model connectivity nodes in some cases.   Note that the if connectivity nodes are in the model, this association would probably not be used as an input specification."@en ;
  cims:multiplicity cims:M:0..1 ;
  owl:inverseOf cim:TopologicalNode.Terminal ;
  rdfs:domain cim:Terminal ;
  rdfs:range cim:TopologicalNode .

