  rdfs:comment "A bidding zone is a market-based method for handling power transmission congestion. It consists of scheduling areas that include the relevant production (supply) and consumption (demand) to form an electrical area with the same market price without capacity allocation."@en ;
  rdfs:subClassOf cim:PowerSystemResource .

nc:BiddingZoneBorder ;
  rdfs:label "BiddingZoneBorder" ;
  rdfs:comment "Defines the aggregated connection capacity between two Bidding Zones."@en ;
  rdfs:subClassOf cim:PowerSystemResource .

nc:SchedulingArea ;
  rdfs:label "SchedulingArea" ;
  rdfs:comment "An area where production and/or consumption of energy can be forecasted, scheduled and measured. The area is operated by only one system operator, typically a Transmission System Operator (TSO). The area can consist of a sub area, which has the same definition as the main area, but it can be operated by another system operator (typically Distributed System Operator (DSO) or a Closed Distributed System Operator (CDSO)). This includes microgrid concept. A substation is the smallest grouping that can"@en ;
  rdfs:subClassOf cim:PowerSystemResource .

nc:BiddingZone.BiddingZoneBorderTwo ;
  a owl:ObjectProperty ;
  a owl:InverseFunctionalProperty ;
  rdfs:label "BiddingZoneBorderTwo" ;
  rdfs:comment "The secondary side of the border."@en ;
  cims:multiplicity cims:M:0..n ;
  owl:inverseOf nc:BiddingZoneBorder.BiddingZoneTwo ;
  rdfs:domain nc:BiddingZone ;
  rdfs:range nc:BiddingZoneBorder .

nc:BiddingZone.SchedulingArea ;
  a owl:ObjectProperty ;
  a owl:InverseFunctionalProperty ;
  rdfs:label "SchedulingArea" ;
  rdfs:comment "The scheduling area that has bidding zone."@en ;
  cims:multiplicity cims:M:1..n ;
  owl:inverseOf nc:SchedulingArea.BiddingZone ;
  rdfs:domain nc:BiddingZone ;
  rdfs:range nc:SchedulingArea .

